/*
 * aim.cpp
 *
 * Projects entity head positions into screen space and returns a smoothed
 * crosshair delta for the closest target that falls within a 240 px cone.
 *
 * Usage
 *   Call get_aim_delta() once per frame.  It retains exponential-smoothing
 *   state internally.  Pass a zero-sized span (or all-dead entities) to let
 *   the residual decay away on its own.
 */

#include "aim.h"

#include <cmath>
#include <optional>
#include <span>

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

namespace {

// Project a world-space position through a combined view-projection matrix
// and return pixel coordinates, or nullopt when the point is behind the
// near plane.
//
// The VP matrix is assumed column-major (OpenGL / GLSL convention):
//   transformed.x = vp[0]*wx + vp[4]*wy + vp[8]*wz  + vp[12]
//   etc.
std::optional<Vec2> world_to_screen(
    Vec3        world_pos,
    const Mat4& vp,
    float       screen_w,
    float       screen_h)
{
    // Multiply by the 4×4 VP matrix
    const float x = vp[0]  * world_pos.x + vp[4]  * world_pos.y
                  + vp[8]  * world_pos.z  + vp[12];
    const float y = vp[1]  * world_pos.x + vp[5]  * world_pos.y
                  + vp[9]  * world_pos.z  + vp[13];
    const float w = vp[3]  * world_pos.x + vp[7]  * world_pos.y
                  + vp[11] * world_pos.z  + vp[15];

    // Discard anything behind (or on) the near plane
    if (w <= 0.001f)
        return std::nullopt;

    // Perspective divide → NDC in [-1, 1]
    const float ndcX =  x / w;
    const float ndcY = -y / w;   // flip Y: NDC +Y is up, screen +Y is down

    // Map NDC to pixel coordinates
    return Vec2 {
        (ndcX + 1.0f) * 0.5f * screen_w,
        (ndcY + 1.0f) * 0.5f * screen_h
    };
}

// Euclidean distance between two 2-D points
float dist2(Vec2 a, Vec2 b)
{
    const float dx = a.x - b.x;
    const float dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}

} // anonymous namespace

// ---------------------------------------------------------------------------
// Module-level smoothing state
// ---------------------------------------------------------------------------

static Vec2 s_smoothed { 0.0f, 0.0f };

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

Vec2 get_aim_delta(
    std::span<const Entity> entities,
    const Mat4&             vp,
    float                   screen_w,
    float                   screen_h,
    Vec2                    crosshair,
    float                   cone_radius_px,
    float                   smooth_factor)
{
    // --- 1. Find the closest projected head inside the cone -----------------

    float best_dist = cone_radius_px;   // reject anything farther away
    Vec2  best_pos  { 0.0f, 0.0f };
    bool  found     = false;

    for (const Entity& e : entities) {
        if (!e.is_alive)
            continue;

        const auto screen = world_to_screen(e.head_pos, vp, screen_w, screen_h);
        if (!screen)
            continue;

        const float d = dist2(*screen, crosshair);
        if (d < best_dist) {
            best_dist = d;
            best_pos  = *screen;
            found     = true;
        }
    }

    // --- 2. Compute smoothed delta ------------------------------------------

    if (!found) {
        // No target in cone — decay residual drift toward zero
        s_smoothed.x *= (1.0f - smooth_factor);
        s_smoothed.y *= (1.0f - smooth_factor);
        return { 0.0f, 0.0f };
    }

    // Raw pixel delta from crosshair to nearest head
    const Vec2 raw {
        best_pos.x - crosshair.x,
        best_pos.y - crosshair.y
    };

    // Exponential (lerp-based) smoothing: blend the running estimate
    // toward the raw delta each frame.
    s_smoothed.x += (raw.x - s_smoothed.x) * smooth_factor;
    s_smoothed.y += (raw.y - s_smoothed.y) * smooth_factor;

    return s_smoothed;
}

void reset_aim_state()
{
    s_smoothed = { 0.0f, 0.0f };
}
